/// <reference types="vite/client" />

interface ImportMetaEnv {
  // Переменных окружения у сборки нет специально: в частности, здесь никогда
  // не должно появляться значение с абсолютным адресом SDK (внутреннее
  // хранилище сервиса) — Консоль отклоняет архив с ним в любом виде.
  // Для интеграции «свой домен (iframe)» адрес ставится тегом <script>
  // в хостинг-HTML на своём домене, а не в исходниках (см. src/game/yandex.ts).
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}
